import { errorMessage } from '../lib/api';

/** Device failures are shared by recording, personal calls and team calls. */
export function voiceErrorMessage(error: unknown): string {
  const name = error && typeof error === 'object' && 'name' in error ? String(error.name) : '';
  const message = typeof error === 'string' ? error : errorMessage(error);
  if (/NotFoundError|DevicesNotFoundError/.test(name) || /requested device not found|no (audio )?input device|no microphone/i.test(message))
    return '未找到麦克风，请连接后重试。';
  if (/NotAllowedError|PermissionDeniedError/.test(name) || /permission denied|permission dismissed/i.test(message))
    return '麦克风未获允许，请在浏览器中开启权限。';
  if (/NotReadableError|TrackStartError/.test(name) || /could not start audio source|device in use/i.test(message))
    return '麦克风无法启动，请关闭其他录音后重试。';
  if (name === 'OverconstrainedError') return '麦克风不支持所需格式，请换一个设备。';
  if (name === 'SecurityError') return '当前页面无法使用麦克风，请通过 HTTPS 打开。';
  return message;
}

import React, { useEffect, useRef, useState } from 'react';
import { Check, Eye, X } from '@phosphor-icons/react';
import type { AssistantCandidate } from '@ai-xiutu/contracts';
import { t } from '../i18n';
import { errorMessage } from '../lib/api';
import { assistantEditorKey, type AssistantEditorState } from './assistantGuards';

export interface PreviewControls {
  pending: boolean;
  saving?: boolean;
  onConfirm: () => void | Promise<void>;
  onCancel: () => void;
}

export function candidateMatchesEditor(
  candidate: AssistantCandidate,
  editor: AssistantEditorState,
  field: 'baseRecipe' | 'recipe',
): boolean {
  if (!editor.loggedIn || !editor.projectId || !editor.assetId || candidate.kind !== 'edit' || candidate.artworkId !== editor.artworkId || candidate.baseVersion !== editor.version)
    return false;
  try {
    return assistantEditorKey(editor) === assistantEditorKey({ ...editor, recipe: candidate[field] as AssistantEditorState['recipe'] });
  } catch {
    return false;
  }
}

/** A recorded preview decision remains reversible until a real version is saved. */
export function CandidateActions({
  candidate, editor, controls, disabled, canExecute, onDecision,
}: {
  candidate: AssistantCandidate;
  editor: AssistantEditorState;
  controls?: PreviewControls;
  disabled: boolean;
  canExecute: boolean;
  onDecision: (candidate: AssistantCandidate, decision: 'previewed' | 'rejected') => void;
}) {
  const [error, setError] = useState('');
  const confirming = useRef(false);
  const mounted = useRef(true);
  const [confirmBusy, setConfirmBusy] = useState(false);
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);
  const isEdit = candidate.kind === 'edit';
  const previewing = isEdit && controls?.pending && candidateMatchesEditor(candidate, editor, 'recipe');
  const available = !isEdit || candidateMatchesEditor(candidate, editor, 'baseRecipe');
  const applied = !!candidate.appliedRevisionId;
  const rejected = candidate.decision === 'rejected';
  const locked = disabled || controls?.saving || confirmBusy;
  async function confirm() {
    if (!controls || confirming.current || locked) return;
    confirming.current = true;
    setConfirmBusy(true);
    setError('');
    try { await controls.onConfirm(); }
    catch (failure) { if (mounted.current) setError(errorMessage(failure)); }
    finally { confirming.current = false; if (mounted.current) setConfirmBusy(false); }
  }
  return (
    <div className="candidate-action-region">
      <div className="candidate-actions" data-previewing={previewing || undefined}>
        {previewing ? <>
          <button type="button" className="ai-candidate-primary" disabled={locked} onClick={() => void confirm()}>
            <Check size={16} />{t(locked ? '正在确认…' : '确认修改')}
          </button>
          <button type="button" disabled={locked} onClick={() => { setError(''); controls.onCancel(); }}>
            <X size={16} />{t('取消预览')}
          </button>
        </> : <>
          <button type="button" className="ai-candidate-primary" disabled={locked || !canExecute || applied || rejected || !available}
            onClick={() => { setError(''); onDecision(candidate, 'previewed'); }}>
            <Eye size={16} />
            {t(applied ? '已保存新版本' : rejected ? '已退回' : !available ? '版本或参数已变化' : isEdit
              ? candidate.decision === 'previewed' ? '重新预览' : '在画布预览'
              : candidate.decision === 'previewed' ? '重新打开生图草案' : '选择模型与规格')}
          </button>
          {!applied && !rejected && <button type="button" disabled={locked} onClick={() => onDecision(candidate, 'rejected')}>
            <X size={16} />{t('退回')}
          </button>}
        </>}
      </div>
      {error && <p className="parameter-error" role="alert">{t(error)}</p>}
    </div>
  );
}

