/**
 * Disposable protocol fixture for the manual UI QA server.
 * This module never opens a vendor connection. Product handlers, PostgreSQL,
 * permission checks, event replay, candidate guards and settlement remain real.
 */
import { createHash } from 'node:crypto';
import WebSocket, { WebSocketServer } from 'ws';
import { assistantModelConfigSchema } from '@ai-xiutu/assistant';

const digest = (value) => createHash('sha256').update(value).digest('hex');
export const manualAssistantModelId = 'manual-protocol-r5';

export async function createManualAssistantFixture({ databaseUrl, isolated }) {
  const database = new URL(databaseUrl);
  if (
    isolated !== true ||
    process.env.NODE_ENV === 'production' ||
    !['127.0.0.1', 'localhost', '[::1]'].includes(database.hostname) ||
    !/^\/manual_test_[a-f\d]+$/.test(database.pathname)
  ) throw new Error('Assistant fixture requires the disposable manual test database.');

  let dispatches = 0;
  const vendor = new WebSocketServer({ host: '127.0.0.1', port: 0 });
  await new Promise((resolve, reject) => {
    vendor.once('listening', resolve);
    vendor.once('error', reject);
  });
  const address = vendor.address();
  if (!address || typeof address === 'string') throw new Error('Local voice fixture did not bind.');
  vendor.on('connection', (socket) => {
    let sentInput = false;
    socket.on('message', (bytes) => {
      let event;
      try { event = JSON.parse(String(bytes)); } catch { socket.close(1003); return; }
      const send = (value) => { if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(value)); };
      if (event.type === 'session.start') send({ type: 'session.started', session: { id: 'manual-live-protocol' } });
      if (event.type === 'session.update') send({ type: 'session.updated', session: { id: 'manual-realtime-protocol' } });
      if (['session.input_audio.append', 'input_audio_buffer.append'].includes(event.type) && !sentInput) {
        sentInput = true;
        send({ type: 'session.input_transcript.delta', item_id: 'manual-input', delta: '本地协议已收到音频。', start_ms: 0, end_ms: 1000 });
      }
      if (event.type === 'session.close') send({ type: 'session.closed', usage: { seconds: 1 } });
    });
  });

  const workspace = {
    title: '曝光调整',
    sections: [
      { type: 'candidates', title: '画面预览', candidateIndexes: [0] },
      { type: 'parameters', title: '调整明细', candidateIndexes: [0] },
      { type: 'budget', title: '本轮用量' },
    ],
  };
  const text = '已准备 +0.60 EV 的曝光候选。可先在画布预览，再确认或取消。';
  const outputText = { type: 'message', role: 'assistant', content: [{ type: 'output_text', text }] };
  const dependencies = {
    env: { AI_ASSISTANT_ENABLED: 'true', AI_VOICE_ENABLED: 'true', OPENAI_API_KEY: 'manual-protocol-not-a-provider-key' },
    textModerator: {
      configured: true,
      async check(value) { return { decision: 'passed', inputHash: digest(value), requestId: 'manual-text-protocol' }; },
    },
    imageModerator: {
      configured: true,
      async check(value) { return { decision: 'passed', inputHash: digest(value), requestId: 'manual-image-protocol' }; },
    },
    connectVoice() { return new WebSocket(`ws://127.0.0.1:${address.port}`); },
    async fetcher(_url, init) {
      // Never fall through to global fetch, including malformed requests.
      const body = JSON.parse(String(init?.body));
      if (!Array.isArray(body.input)) throw new Error('Manual fixture only supports editor turns.');
      const ordinal = ++dispatches;
      const hasCandidate = body.input.some((item) => item.type === 'function_call' && item.call_id === 'manual-edit');
      const output = hasCandidate ? [outputText] : [
        { type: 'function_call', name: 'propose_edit', call_id: 'manual-edit', arguments: JSON.stringify({ summary: '曝光调整为 +0.60 EV', target: 'global', targetId: null, changes: [{ path: 'adjustments.exposure', value: 0.6 }] }) },
        { type: 'function_call', name: 'compose_workspace', call_id: 'manual-workspace', arguments: JSON.stringify(workspace) },
      ];
      const response = { id: `manual-response-${ordinal}`, status: 'completed', output, usage: { input_tokens: 100, output_tokens: 50, total_tokens: 150 } };
      if (!body.stream) return Response.json(response, { headers: { 'x-request-id': `manual-protocol-${ordinal}` } });
      const encoder = new TextEncoder();
      return new Response(new ReadableStream({
        start(controller) {
          if (hasCandidate) controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: 'response.output_text.delta', delta: text })}\n\n`));
          controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: 'response.completed', response })}\n\n`));
          controller.close();
        },
      }), { headers: { 'content-type': 'text/event-stream', 'x-request-id': `manual-protocol-${ordinal}` } });
    },
  };
  return {
    dependencies,
    async seedModels(db) {
      for (const [id, label, operations] of [
        [manualAssistantModelId, '本地协议验收 · 无供应商调用', ['assistant-turn']],
        ['gpt-live-1', 'Live 协议验收 · 本地连接', ['realtime-voice']],
        ['gpt-realtime-2.1', 'Realtime 协议验收 · 本地连接', ['realtime-voice']],
      ]) {
        const config = assistantModelConfigSchema.parse({ label, enabled: true, provider: 'openai', operations, unitCost: 1, imageInput: true, webSearch: false, webImageSearch: false, maxSeconds: 60, maxDelegations: 2 });
        await db.query('INSERT INTO assistant_model_configs(id, config) VALUES($1,$2) ON CONFLICT(id) DO UPDATE SET config=EXCLUDED.config', [id, JSON.stringify(config)]);
      }
    },
    async close() {
      for (const socket of vendor.clients) socket.terminate();
      await new Promise((resolve) => vendor.close(resolve));
    },
  };
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createRecipeV4 } from '@ai-xiutu/editor';
import type { AssistantCandidate } from '@ai-xiutu/contracts';
import { CandidateActions, candidateMatchesEditor } from '../src/ai/CandidateActions.tsx';
import { acknowledgeEditCandidate, type AssistantEditorState } from '../src/ai/assistantGuards.ts';

test('a preview can be cancelled and reopened without changing its recorded decision or bypassing the base check', async () => {
  const editor: AssistantEditorState = { loggedIn: true, projectId: 'project', spaceId: 'space', artworkId: 'artwork', assetId: 'asset', version: 3, recipe: createRecipeV4() };
  const candidate: AssistantCandidate = { id: 'candidate', kind: 'edit', summary: 'Exposure', artworkId: editor.artworkId, baseVersion: 3, baseRecipeHash: 'server-owned', baseRecipe: structuredClone(editor.recipe), recipe: createRecipeV4({ adjustments: { exposure: 0.6 } }), decision: 'pending' };
  let acknowledgements = 0;
  const open = () => acknowledgeEditCandidate(candidate, {
    readCurrent: () => editor,
    isActive: () => true,
    acknowledge: async () => { acknowledgements += 1; },
    apply: (recipe) => { editor.recipe = recipe; },
  });
  await open();
  candidate.decision = 'previewed';
  assert.equal(candidateMatchesEditor(candidate, editor, 'recipe'), true);
  const previewMarkup = renderToStaticMarkup(createElement(CandidateActions, { candidate, editor, controls: { pending: true, onConfirm() {}, onCancel() {} }, disabled: false, canExecute: true, onDecision() {} }));
  assert.match(previewMarkup, /确认修改/);
  assert.match(previewMarkup, /取消预览/);
  editor.recipe = createRecipeV4();
  const cancelledMarkup = renderToStaticMarkup(createElement(CandidateActions, { candidate, editor, controls: { pending: false, onConfirm() {}, onCancel() {} }, disabled: false, canExecute: true, onDecision() {} }));
  assert.match(cancelledMarkup, /重新预览/);
  assert.doesNotMatch(cancelledMarkup, /disabled=""/);
  assert.equal(candidateMatchesEditor(candidate, editor, 'baseRecipe'), true);
  await open();
  assert.equal(acknowledgements, 2);
  assert.equal(editor.recipe.adjustments.exposure, 0.6);
  editor.version += 1;
  assert.equal(candidateMatchesEditor(candidate, editor, 'baseRecipe'), false);
  assert.equal(candidateMatchesEditor(candidate, editor, 'recipe'), false);
  await assert.rejects(open(), /图片或参数已经变化/);
  assert.equal(acknowledgements, 2, 'stale candidates never reach the acknowledgement endpoint');
});

test('candidate actions remain unavailable after sign-out or with missing source identity', () => {
  const editor: AssistantEditorState = { loggedIn: true, projectId: 'project', spaceId: 'space', artworkId: 'artwork', assetId: 'asset', version: 1, recipe: createRecipeV4() };
  const candidate: AssistantCandidate = { id: 'candidate', kind: 'edit', summary: 'Exposure', artworkId: 'artwork', baseVersion: 1, baseRecipeHash: 'server-owned', baseRecipe: editor.recipe, recipe: createRecipeV4({ adjustments: { exposure: 0.6 } }), decision: 'previewed' };
  assert.equal(candidateMatchesEditor(candidate, { ...editor, loggedIn: false }, 'baseRecipe'), false);
  assert.equal(candidateMatchesEditor(candidate, { ...editor, assetId: null }, 'baseRecipe'), false);
  assert.equal(candidateMatchesEditor(candidate, { ...editor, recipe: createRecipeV4({ adjustments: { contrast: 7 } }) }, 'baseRecipe'), false);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { voiceErrorMessage } from '../src/ai/voice-errors.ts';

test('microphone failures use the same short actionable state across recording and both call types', () => {
  assert.equal(voiceErrorMessage(new DOMException('Requested device not found', 'NotFoundError')), '未找到麦克风，请连接后重试。');
  assert.equal(voiceErrorMessage('Requested device not found'), '未找到麦克风，请连接后重试。');
  assert.equal(voiceErrorMessage(new DOMException('Permission denied', 'NotAllowedError')), '麦克风未获允许，请在浏览器中开启权限。');
  assert.equal(voiceErrorMessage(new DOMException('Could not start audio source', 'NotReadableError')), '麦克风无法启动，请关闭其他录音后重试。');
  assert.equal(voiceErrorMessage(new Error('会话结果待核验')), '会话结果待核验', 'a billing or protocol state must never be relabelled as a device error');
});

