/** Keep valid user choices when the same model ID is reconfigured by operations. */
export function reconcileImageOptions(model: AIModel | undefined, selected: ImageOptions): ImageOptions {
  const defaults = defaultImageOptions(model);
  const caps = model?.parameterCapabilities;
  if (!caps) return {};
  const next = { ...defaults };
  for (const field of ['quality', 'background', 'outputFormat', 'complexity'] as const) {
    const value = selected[field];
    if (caps[field].supported && value && caps[field].values?.includes(value)) next[field] = value;
  }
  if (caps.n.supported && Number.isSafeInteger(selected.n))
    next.n = Math.max(caps.n.min ?? 1, Math.min(caps.n.max ?? 1, selected.n!));
  if (next.background === 'transparent' && next.outputFormat === 'jpeg') {
    const format = caps.outputFormat.values?.find((value) => value === 'png' || value === 'webp');
    if (format) next.outputFormat = format;
    else next.background = caps.background.values?.find((value) => value === 'auto' || value === 'opaque');
  }
  if (caps.outputCompression.supported && caps.outputCompression.formats?.includes(next.outputFormat ?? 'png')) {
    next.outputCompression = Number.isSafeInteger(selected.outputCompression)
      ? Math.max(caps.outputCompression.min ?? 0, Math.min(caps.outputCompression.max ?? 100, selected.outputCompression!))
      : defaults.outputCompression;
  } else delete next.outputCompression;
  return next;
}

export function imageCapabilityKey(model: AIModel | undefined): string {
  if (!model) return '';
  return JSON.stringify([
    model.id, model.operations, model.parameterCapabilities, model.minWidth, model.maxWidth,
    model.minHeight, model.maxHeight, model.minPixels, model.maxPixels, model.maxDimension,
    model.minAspectRatio, model.maxAspectRatio, model.batchLimits, model.maxOutputs,
  ]);
}

test('a capability refresh for the same model removes revoked options and preserves valid choices', () => {
  const previous = model();
  const next = structuredClone(previous);
  next.parameterCapabilities!.quality = { supported: true, values: ['auto', 'low'], default: 'low' };
  next.parameterCapabilities!.n.max = 2;
  next.parameterCapabilities!.outputCompression.max = 75;
  const before = { quality: 'max', background: 'opaque', outputFormat: 'webp', outputCompression: 92, complexity: 'high', n: 4 };
  const repaired = reconcileImageOptions(next, before);
  assert.equal(next.id, previous.id);
  assert.notEqual(imageCapabilityKey(next), imageCapabilityKey(previous));
  assert.deepEqual(repaired, { quality: 'low', background: 'opaque', outputFormat: 'webp', outputCompression: 75, n: 2 });
  assert.equal(imageOptionsError(next, repaired), null);
  assert.deepEqual(requestImageOptions(next, repaired), repaired);
  assert.equal(before.quality, 'max', 'an already-frozen request is not mutated');
  assert.equal(before.n, 4);
});

test('capability refresh resolves dependent format settings before admitting compression', () => {
  const m = model();
  const repaired = reconcileImageOptions(m, { quality: 'low', background: 'transparent', outputFormat: 'jpeg', outputCompression: 72, n: 1 });
  assert.equal(repaired.outputFormat, 'png');
  assert.equal(repaired.outputCompression, undefined);
  assert.equal(imageOptionsError(m, repaired), null);
  m.parameterCapabilities!.n = { supported: false };
  m.parameterCapabilities!.quality = { supported: false };
  assert.equal(reconcileImageOptions(m, repaired).n, undefined);
  assert.equal(reconcileImageOptions(m, repaired).quality, undefined);
  assert.deepEqual(reconcileImageOptions({ ...m, parameterCapabilities: undefined }, repaired), {});
});

