fragments.catalogEffect:
useEffect(() => {
  alive.current = true;
  if (!isLoggedIn || props.visible === false) return;
  let controller: AbortController | undefined;
  const refresh = () => {
    controller?.abort();
    const request = new AbortController();
    controller = request;
    setCatalogLoading(true);
    void Promise.all([
      api<Catalog>('/assistant/models', { signal: request.signal }),
      api<Session>('/session', { signal: request.signal }),
    ])
      .then(([value, session]) => {
        if (request.signal.aborted) return;
        setCatalog(value);
        setSpaces(session.spaces);
        setActorId(session.user?.id ?? null);
        if (catalogSelectionLocked.current) return;
        setModelId((old) =>
          value.models.some((item) => item.id === old && item.operations.includes('assistant-turn'))
            ? old
            : (value.models.find((item) => item.operations.includes('assistant-turn'))?.id ?? ''),
        );
        setVoiceId((old) =>
          value.models.some((item) => item.id === old && item.operations.includes('realtime-voice'))
            ? old
            : (value.models.find((item) => item.operations.includes('realtime-voice'))?.id ?? ''),
        );
      })
      .catch((err) => {
        if (!request.signal.aborted) setError(errorMessage(err));
      })
      .finally(() => {
        if (!request.signal.aborted) setCatalogLoading(false);
      });
  };
  refresh();
  window.addEventListener('focus', refresh);
  window.addEventListener('ai-xiutu:model-catalog-changed', refresh);
  return () => {
    controller?.abort();
    window.removeEventListener('focus', refresh);
    window.removeEventListener('ai-xiutu:model-catalog-changed', refresh);
  };
}, [isLoggedIn, props.visible]);

