const operationEpoch = useRef(0);
useEffect(() => {
  const epoch = ++operationEpoch.current;
  mutation.current = false;
  micChanging.current = false;
  setPending(false);
  setMicBusy(false);
  return () => {
    if (operationEpoch.current === epoch) operationEpoch.current += 1;
  };
}, [room.artworkId, room.state]);

fragments.toggleMic:
async function toggleMic() {
  if (micChanging.current || room.state !== 'connected' || !room.artworkId) return;
  const epoch = operationEpoch.current;
  const ownsRoom = room.ownership(room.artworkId);
  const current = () => operationEpoch.current === epoch && ownsRoom();
  if (!current()) return;
  micChanging.current = true;
  setMicBusy(true);
  try { await room.toggleMic(); }
  catch (failure) { if (current()) room.setMessage(voiceErrorMessage(failure)); }
  finally {
    if (operationEpoch.current === epoch) {
      micChanging.current = false;
      setMicBusy(false);
    }
  }
}

