const imageTask = !!modelEdit?.operations.includes('generate-image');
const providerProfile = providerCatalog.find((item) => item.id === modelEdit?.id && item.provider === modelEdit?.provider);
const savedProfile = models.find((item) => item.id === modelEdit?.id && item.provider === modelEdit?.provider);
const editingCaps = providerProfile?.parameterCapabilities ?? savedProfile?.parameterCapabilities;
const qualityChoices = imageTask && editingCaps?.quality.supported ? editingCaps.quality.values ?? [] : [];
const selectedQualities = qualityChoices.filter((quality) => modelEdit?.allowedQualities.includes(quality));
const maxImageEdge = Math.min(8192, editingCaps?.size.maxDimension ?? providerProfile?.maxDimension ?? 8192);
const maxImageOutputs = editingCaps?.n.supported ? Math.min(10, editingCaps.n.max ?? 1) : 1;
const imageDraftError = imageTask && modelEdit ?
  modelEdit.minWidth > modelEdit.maxWidth || modelEdit.minHeight > modelEdit.maxHeight ? '最小尺寸不能大于最大尺寸。' :
  modelEdit.maxWidth > maxImageEdge || modelEdit.maxHeight > maxImageEdge ? '尺寸超出当前模型范围。' :
  modelEdit.maxOutputs > maxImageOutputs ? '输出数量超出当前模型范围。' :
  qualityChoices.length > 0 && selectedQualities.length === 0 ? '至少选择一个支持的质量档位。' : null : null;
